  "knowledge": "Severe Soiling Condition",
  "description": "Indicates that panel surfaces are heavily soiled, causing a significant loss of energy production.",
  "definition": "A condition met when the Soiling Loss Index for a plant is greater than a significant threshold, for example, 15%."
}

{
